template <typename T = int, size_t N = 1>
class ConfiguredModel {
    T storage[N];
};

// Instantiation using all defaults:
// NOTE: <> is mandatory, even when empty.
ConfiguredModel<> m_default;

// Override T, use default N
ConfiguredModel<float> m_float;

// Override both
ConfiguredModel<bool, 5> m_bool_5;
